function fromMap(map,v){const raw=String(v??'');const a=map?.[raw]||map?.[raw.toUpperCase?.()];return a?tri(a[0],a[1],a[2]):raw}
function statusText(v){return fromMap(SYS.status,v)}function stageText(v){return fromMap(SYS.stage,v)}function categoryText(v){return fromMap(SYS.category,v)}function financeTypeText(v){return fromMap(SYS.financeType,v)}function knownText(v){return fromMap(SYS.known,v)}
function sportText(v){const byKey=SYS.sport[String(SPORT||'').toLowerCase()];if(byKey)return tri(byKey[0],byKey[1],byKey[2]);const raw=String(v||'');for(const a of Object.values(SYS.sport))if(a.includes(raw))return tri(a[0],a[1],a[2]);return raw}
function titleText(v){const raw=String(v||'');if(!/PRODUCTION FIXTURE/i.test(raw))return raw;let out=raw.replace(/PRODUCTION FIXTURE/ig,tri('DỮ LIỆU KIỂM THỬ PRODUCTION','PRODUCTION FIXTURE','正式環境測試資料'));for(const a of Object.values(SYS.sport)){const n=a.find(x=>x&&raw.includes(x));if(n){out=out.split(n).join(tri(a[0],a[1],a[2]));break}}return out}


const PPT_SECTION_META=[
 ['cover','Bìa / Cover'],['summary','Tổng quan'],['champions','Thành tích'],['prizes','Cơ cấu giải thưởng'],['rankings','Bảng xếp hạng'],['results','Lịch & kết quả'],['finance','Tài chính'],['final','Khoảnh khắc'],['thanks','Kết thúc']
];
function pptDefaultTitle(key){const m={cover:L('report'),summary:L('overview'),champions:L('champions'),prizes:L('prizes'),rankings:L('rankings'),results:L('results'),finance:L('finance'),final:finalSectionTitle(),thanks:L('thanks')};return m[key]||key}
function pptPositionForKey(key){return ['summary','champions','prizes','rankings','results','finance','final'].includes(key)?key:null}
function pptImageCount(key){if(key==='cover'||key==='thanks')return images.filter(x=>x.position===key).length;const p=pptPositionForKey(key);return p?images.filter(x=>x.position===p).length:0}
const PPT_BODY_HINTS={
 cover:'TOPKEY | '+REPORT_THEME.label+' | '+new Date().toLocaleDateString('vi-VN'),
 summary:'Objective / M\u1ee5c ti\u00eau:\nLocation / \u0110\u1ecba \u0111i\u1ec3m:\nTime / Th\u1eddi gian:',
 champions:'Highlights / \u0110i\u1ec3m nh\u1ea5n th\u00e0nh t\u00edch:',
 prizes:'Award ceremony / L\u1ec5 trao gi\u1ea3i:\nNotes / Ghi ch\u00fa:',
 rankings:'Standings analysis / Ph\u00e2n t\u00edch b\u1ea3ng x\u1ebfp h\u1ea1ng:',
 results:'Key moments / Di\u1ec5n bi\u1ebfn \u0111\u00e1ng nh\u1edb:',
 finance:'Financial notes / Ghi ch\u00fa t\u00e0i ch\u00ednh:',
 final:'Memorable moments / Kho\u1ea3nh kh\u1eafc \u0111\u00e1ng nh\u1edb:',
 thanks:'Thank you / C\u1ea3m \u01a1n ban t\u1ed5 ch\u1ee9c v\u00e0 ng\u01b0\u1eddi tham gia.'
};

// H112: a per-sport presentation profile shared by production and Test Lab.
const PPT_PLAN_KEY='topkey_ppt_profile_h112_'+SPORT;
let pptPlanTimer=null;
function readSavedPptPlan(){try{const obj=JSON.parse(localStorage.getItem(PPT_PLAN_KEY)||'null');if(!obj||obj.schema!==1||obj.sport!==SPORT)return {};return obj.sections&&typeof obj.sections==='object'?obj.sections:{}}catch{return {}}}
function savePptPlan(){try{const sections=readPptStructure();localStorage.setItem(PPT_PLAN_KEY,JSON.stringify({schema:1,sport:SPORT,updatedAt:Date.now(),sections}));const st=$('tk79-status');if(st&&reportRef)st.textContent='Đã lưu cấu trúc PowerPoint cho riêng môn '+SPORT+' (kể cả Test Lab).';return true}catch(e){console.warn('PPT profile storage',e);return false}}
function schedulePptSave(){clearTimeout(pptPlanTimer);pptPlanTimer=setTimeout(savePptPlan,200)}
function readPptStructure(){const host=$('tk88-ppt-structure-host'),out={};if(host)host.querySelectorAll('.tk88-ppt-item').forEach(row=>{const key=row.dataset.key;out[key]={enabled:!!row.querySelector('.tk88-enabled')?.checked,title:String(row.querySelector('.tk88-title')?.value||pptDefaultTitle(key)).trim()||pptDefaultTitle(key),dirty:row.querySelector('.tk88-title')?.dataset.dirty==='1',custom:!!row.querySelector('.tk105-edit')?.checked,body:String(row.querySelector('.tk105-body')?.value||'').slice(0,2500)}});for(const [key] of PPT_SECTION_META)if(!out[key])out[key]={enabled:true,title:pptDefaultTitle(key),dirty:false,custom:false,body:PPT_BODY_HINTS[key]||''};return out}
function updatePptImageCounts(){for(const [key] of PPT_SECTION_META){const n=$(`tk88-count-${key}`);if(n)n.textContent=`Ảnh: ${pptImageCount(key)}`}}
function renderPptStructure(preserve=true){
 const host=$('tk88-ppt-structure-host');if(!host)return;
 const old=preserve?readPptStructure():readSavedPptPlan();
 host.innerHTML=`<div class="tk88-ppt-head"><div><h3 style="margin:0">PowerPoint TOPKEY | ${esc(REPORT_THEME.label)}</h3><div class="tk79-note">16:9 | ${'\u0110\u00e1nh d\u1ea5u m\u1ee5c c\u1ea7n xu\u1ea5t, s\u1eeda ti\u00eau \u0111\u1ec1, tick N\u1ed9i dung tu\u1ef3 ch\u1ec9nh v\u00e0 g\u00e1n \u1ea3nh theo m\u1ee5c. T\u1ea5t c\u1ea3 ch\u1eef trong PPTX \u0111\u1ec1u s\u1eeda \u0111\u01b0\u1ee3c.'}</div></div><span class="tk88-photo-count">${esc(REPORT_THEME.label)}</span></div><div class="tk88-ppt-grid">${PPT_SECTION_META.map(([key,label],idx)=>{const o=old[key]||{},title=o.dirty?o.title:pptDefaultTitle(key),body=o.body??PPT_BODY_HINTS[key]??'';return `<div class="tk88-ppt-item tk105-ppt-item" data-key="${key}"><div class="tk105-ppt-row"><label><input class="tk88-enabled" type="checkbox" ${o.enabled===false?'':'checked'}> <b>${idx+1}. ${label}</b></label><span id="tk88-count-${key}" class="tk88-photo-count">${pptImageCount(key)} ${'\u1ea3nh'}</span></div><input class="tk88-title" type="text" value="${esc(title)}" data-dirty="${o.dirty?'1':'0'}" aria-label="Slide title"><label class="tk105-ppt-row"><input type="checkbox" class="tk105-edit" ${o.custom?'checked':''}> ${'\u270d N\u1ed9i dung tu\u1ef3 ch\u1ec9nh (th\u00eam slide ghi ch\u00fa s\u1eeda \u0111\u01b0\u1ee3c)'}</label><textarea class="tk105-body" rows="3" maxlength="2500" placeholder="Notes / Custom editable text">${esc(body)}</textarea><label class="tk105-ppt-upload">${'\ud83d\udcf7 Th\u00eam \u1ea3nh v\u00e0o m\u1ee5c n\u00e0y'}<input type="file" class="tk105-section-files" data-key="${key}" accept="image/jpeg,image/png,image/webp" multiple></label></div>`}).join('')}</div>`;
 host.querySelectorAll('.tk88-title').forEach(x=>x.oninput=()=>{x.dataset.dirty='1';schedulePptSave()});
 if(!host.dataset.tk112Listener){host.dataset.tk112Listener='1';host.addEventListener('input',schedulePptSave);host.addEventListener('change',schedulePptSave);}
 host.querySelectorAll('.tk105-section-files').forEach(x=>x.onchange=async()=>{const f=[...(x.files||[])];if(f.length)await addFiles(f,x.dataset.key);x.value=''});
}
function pptTitle(key,structure){return structure?.[key]?.title||pptDefaultTitle(key)}
function pptEnabled(key,structure){return structure?.[key]?.enabled!==false}
function downloadPptPlan(){if(!reportRef)return;const st=readPptStructure(),rows=PPT_SECTION_META.map(([key,label],i)=>`<tr><td>${i+1}</td><td>${esc(label)}</td><td>${st[key].enabled?'✓':'—'}</td><td>${esc(st[key].title)}</td><td>${pptImageCount(key)}</td></tr>`).join('');const html=`<!doctype html><html><head><meta charset="utf-8"><title>Cấu trúc PowerPoint</title><style>body{font:15px Arial;margin:32px;color:#2c1b18}h1{color:#5B342B}table{width:100%;border-collapse:collapse}th,td{border:1px solid #c8b5ae;padding:9px}th{background:#5B342B;color:white}</style></head><body><h1>Cấu trúc PowerPoint - ${esc(titleText(reportRef.title))}</h1><p>Phong cách TKT 16:9: nền nâu, điểm nhấn vàng. Ảnh được chèn ngay sau mục đã gán.</p><table><thead><tr><th>#</th><th>Mục</th><th>Dùng</th><th>Tiêu đề</th><th>Số ảnh</th></tr></thead><tbody>${rows}</tbody></table></body></html>`;downloadBlob(reportFileBase(reportRef)+'_PPT-STRUCTURE.html',new Blob([html],{type:'text/html;charset=utf-8'}));$('tk79-status').textContent='Downloaded the editable PPT plan.'}

