function loadScript(src,global){if(window[global])return Promise.resolve(window[global]);return new Promise((res,rej)=>{const s=document.createElement('script');s.src=src;s.onload=()=>res(window[global]);s.onerror=()=>rej(new Error('Không tải được thư viện xuất file'));document.head.appendChild(s)})}
